  "passages": [
    {
      "id": "P1",
      "text": "ENDOSCOPY NOTE - EGD AND COLONOSCOPY, SAME SESSION"
    },
    {
      "id": "P2",
      "text": "Service date: Oct 14, 2026"
    },
    {
      "id": "P3",
      "text": "Endoscopist: Synthetic Endoscopist, MD (fictional)"
    },
    {
      "id": "P4",
      "text": "Past history: ERCP with biliary sphincterotomy and stone extraction at another hospital in 2023, followed by laparoscopic cholecystectomy."
    },
    {
      "id": "P5",
      "text": "EGD"
    },
    {
      "id": "P6",
      "text": "Gastroscope passed under direct vision through the esophagus and stomach to the second part of the duodenum."
    },
    {
      "id": "P7",
      "text": "Patchy erythema in the antrum, no erosions or ulcers."
    },
    {
      "id": "P8",
      "text": "The major papilla shows a healed sphincterotomy."
    },
    {
      "id": "P9",
      "text": "Biopsies, cold forceps: antrum and body for H. pylori (jar 1); duodenal bulb and second portion for celiac disease (jar 2)."
    },
    {
      "id": "P10",
      "text": "COLONOSCOPY"
    },
    {
      "id": "P11",
      "text": "The colonoscope was inserted and advanced under direct vision."
    },
    {
      "id": "P12",
      "text": "Sigmoid colon, 30 cm: 10 mm sessile polyp, removed en bloc with a cold snare and retrieved (jar 3)."
    },
    {
      "id": "P13",
      "text": "Because she takes aspirin, one clip was placed to close the defect; no bleeding was seen before or after."
    },
    {
      "id": "P14",
      "text": "1. 2 cm hiatal hernia; mild antral erythema, biopsied."
    },
    {
      "id": "P15",
      "text": "2. Normal-appearing duodenum, biopsied for celiac disease."
    },
    {
      "id": "P16",
      "text": "3. Healed sphincterotomy at the papilla from the 2023 ERCP."
    },
    {
      "id": "P17",
      "text": "4. 10 mm sigmoid polyp removed with cold snare; prophylactic clip placed."
    },
    {
      "id": "P18",
      "text": "- No endoscopy was done today; the narratives above are from 2023."
    }
  ],
